import Appointment from '../models/Appointment.js';

// @desc    Get booked slots for a specific date
// @route   GET /api/appointments/booked-slots?date=YYYY-MM-DD
export const getBookedSlots = async (req, res, next) => {
  try {
    const { date } = req.query;
    if (!date) {
      return res.status(400).json({ message: 'Date query parameter is required' });
    }

    const appointments = await Appointment.find({ 
      appointmentDate: date, 
      status: { $ne: 'CANCELLED' } 
    }).select('timeSlot');
    
    const bookedSlots = appointments.map(app => app.timeSlot);
    res.json(bookedSlots);
  } catch (error) {
    next(error);
  }
};

// @desc    Book a new appointment
// @route   POST /api/appointments
export const createAppointment = async (req, res, next) => {
  try {
    const { 
      customerName, 
      customerPhone, 
      customerEmail, 
      service, 
      servicePrice, 
      appointmentDate, 
      timeSlot,
      paymentMethod,
      paymentStatus
    } = req.body;

    if (!customerName || !customerPhone || !service || !appointmentDate || !timeSlot) {
      return res.status(400).json({ message: 'Please fill in all required appointment fields' });
    }

    // Check if slot is already taken for that date
    const existing = await Appointment.findOne({ 
      appointmentDate, 
      timeSlot, 
      status: { $ne: 'CANCELLED' } 
    });

    if (existing) {
      return res.status(400).json({ message: 'This time slot is already booked!' });
    }

    const appointment = await Appointment.create({
      customerName,
      customerPhone,
      customerEmail,
      service,
      servicePrice: servicePrice || 0,
      appointmentDate,
      timeSlot,
      paymentMethod: paymentMethod || 'STUDIO',
      paymentStatus: paymentStatus || 'PENDING'
    });

    // Wrapped response so data.appointment._id works on the frontend
    res.status(201).json({
      message: 'Appointment booked successfully',
      appointment
    });
  } catch (error) {
    next(error);
  }
};

// @desc    Get all appointments (Admin)
// @route   GET /api/appointments
export const getAllAppointments = async (req, res, next) => {
  try {
    const appointments = await Appointment.find().sort({ createdAt: -1 });
    res.json(appointments);
  } catch (error) {
    next(error);
  }
};

// @desc    Update appointment status (Admin)
// @route   PUT /api/appointments/:id/status
export const updateAppointmentStatus = async (req, res, next) => {
  try {
    const { status } = req.body;
    const appointment = await Appointment.findById(req.params.id);

    if (!appointment) {
      return res.status(404).json({ message: 'Appointment not found' });
    }

    appointment.status = status;
    const updated = await appointment.save();
    res.json(updated);
  } catch (error) {
    next(error);
  }
};